  header .brand{font-family:'Archivo Black',sans-serif;letter-spacing:.14em;text-transform:uppercase;font-size:14px}
  header nav a{color:var(--white);text-decoration:none;font-size:13px;letter-spacing:.12em;text-transform:uppercase;font-weight:600}
  header nav a:hover{color:var(--yellow)}
  header nav{display:flex;gap:22px}

  /* Hero = the composition itself, built as a Mondrian grid */
  .hero{border-bottom:var(--thick) solid var(--line)}
