  .c-title{grid-row:1/3;grid-column:1;background:var(--white)}
  .c-white{grid-row:2;grid-column:2/4;background:var(--white)}
  .c-blue{grid-row:3;grid-column:1/2;background:var(--blue);color:var(--white);justify-content:flex-end}
