    font-size:clamp(34px,6vw,72px);
    line-height:1.02;text-transform:uppercase;letter-spacing:-.01em;
  }
  .kicker{font-size:13px;font-weight:800;letter-spacing:.22em;text-transform:uppercase;margin-bottom:18px}
  .c-title .kicker{color:var(--black)}
  .meta{margin-top:22px;font-size:clamp(15px,1.6vw,19px)}
  .meta strong{font-weight:800}
  h2{font-family:'Archivo Black',sans-serif;text-transform:uppercase;font-size:clamp(18px,2.4vw,26px);line-height:1.1}
  .c-red h2{margin-bottom:10px}
  p{max-width:52ch}
  .c-blue p{font-size:15px}

  /* Facts strip */
  .facts{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:var(--thick) solid var(--line)}
  .fact{padding:26px 24px;border-right:var(--thick) solid var(--line)}
  .fact:last-child{border-right:none}
  .fact dt{font-size:11px;font-weight:800;letter-spacing:.2em;text-transform:uppercase;opacity:.6}
  .fact dd{font-weight:800;font-size:16px;margin-top:6px}

  /* Story sections */
  section.story{padding:64px 0;border-bottom:var(--thick) solid var(--line)}
  section.story .wrap{display:grid;grid-template-columns:1fr 2fr;gap:32px}
